package ru.railbrake.calculator.core

/**
 * Предметные деревья для критичных карточек, которые в расширенном каталоге
 * начинались с универсального шаблона. Здесь уточняется наблюдение и граница
 * допуска, но не добавляются ремонтные операции или обходы защит.
 */
object DiagnosticDeepening {
    fun enrich(scenario: DiagnosticScenario): DiagnosticScenario = when (scenario.id) {
        "aux-common-loss" -> scenario.deepen(
            questions = listOf(
                q("aux-scope", "Остановились все вспомогательные машины или только одна группа?", "Общая причина питания или управления вероятнее локального отказа двигателя.", "Проверять цепь конкретной машины, её контактор и защиту.", "aux-phase"),
                q("aux-phase", "Фазорасщепитель работает и его состояние подтверждено?", "Разделять потерю общего питания и отказ отходящей цепи.", "Не считать отказы нескольких машин независимыми; проверить общую цепь собственных нужд.", "aux-cooling"),
                q("aux-cooling", "Потеряны охлаждение или запас сжатого воздуха?", "Снять связанную нагрузку и не допускать работы оборудования без охлаждения/воздуха.", "Зафиксировать состав отключившихся потребителей и последовательность события.", DiagnosticRepository.END_OF_FLOW)
