                q("long-leak", "После остановки компрессора давление заметно падает без ожидаемого расхода?", "Искать утечку по доступным признакам и локализовать систему.", "Проверять регулятор давления и фактическую верхнюю границу отключения.", "long-cutoff"),
                q("long-cutoff", "Компрессор продолжает работать после достижения обычной верхней границы?", "Вероятна цепь регулятора/контактора; не допускать перегрева и передать аппарат на проверку.", "Длительная работа может быть связана с производительностью или расходом воздуха; сначала оценить достоверность показания.", "long-gauge", yesNext = DiagnosticRepository.END_OF_FLOW),
