                q("bi-mode", "Неравномерность появляется и при автоматическом, и при независимом торможении?", "Общая для ТЦ/механики причина вероятнее одного органа управления.", "Разделять автоматическую и независимую управляющие ветви.", "bi-release"),
                q("bi-release", "После отпуска одна группа ТЦ сохраняет давление или колодки не отходят?", "Риск нагрева и юза: движение до оценки безопасности не начинать.", "Проверять недостаточное наполнение, утечку или механический дефект другой группы.", DiagnosticRepository.END_OF_FLOW)
            ),
            causes = listOf("Утечка или сопротивление отдельной ветви ТЦ.", "Неодинаковая работа РД/клапанов по секциям.", "Недостоверное показание манометра.", "Перекос или повреждение рычажной передачи.", "Неотход колодок или ручного тормоза.", "Различие управляющих ветвей автоматического и независимого торможения."),
            checks = listOf(
