            causes = listOf("Саморасцепление или неполное сцепление.", "Трещина либо деформация корпуса автосцепки.", "Повреждение замка, подъёмника, центрирующего или упряжного устройства.", "Смещение высоты автосцепки после повреждения подвешивания.", "Ударная нагрузка с нарушением тормозной магистрали."),
            checks = listOf(
                cab("Первое событие", "Зафиксировать характер удара, изменение ТМ, рывок и факт разделения состава.", "Понятно, требуется ли порядок разрыва поезда.", "При падении ТМ и разделении состава не ограничиваться осмотром автосцепки."),
                stop("Осмотр после закрепления", "После полного закрепления осмотреть доступные части автосцепки без нахождения между единицами при возможности их движения.", "Нет трещин, деформации и нештатного положения.", "При любом сомнении движение и манёвры не начинать."),
                authorized("Сцепное устройство", "Проверить замок, корпус, центрирующий и упряжной узлы по технологии осмотра.", "Исправность и надёжность сцепления подтверждены.", "После соединения выполнить предусмотренную проверку целостности ТМ и тормозов.")
            ),
            related = listOf("brake-pipe-leak", "external-object-impact", "mechanical-noise-heating", "brake-rigging-damage")
        ).copy(
            severity = DiagnosticSeverity.STOP_AND_REPORT,
            immediateActions = listOf(
                "При саморасцеплении, разрыве поезда или падении давления в ТМ немедленно действовать по порядку разрыва поезда и закрепить части состава.",
                "Сообщить ДНЦ/ДСП и после полного закрепления осмотреть сцепное устройство, не находясь между подвижными единицами при возможности их движения.",
                "Сцепление, целостность ТМ и действие тормозов должны быть подтверждены установленной проверкой до возобновления движения."
            ),
            sourceNote = "Распоряжение ОАО «РЖД» № 2580р, раздел 6.8, редакция 18.02.2025; руководство по эксплуатации автосцепного устройства и местный порядок."
        )

        else -> scenario
    }

    private fun DiagnosticScenario.deepen(
        questions: List<DiagnosticQuestion>,
        causes: List<String>,
        checks: List<DiagnosticCheck>,
        related: List<String>
    ) = copy(
        questions = questions,
        probableCauses = causes,
        checks = checks,
        relatedScenarioIds = related,
        trainingNotes = listOf(
            "Сначала сопоставьте команду, прибор и фактическое действие системы.",
            "Отделяйте общий отказ источника от локальной ветви или механизма.",
            "Не воспроизводите опасный режим ради подтверждения гипотезы."
        ),
        feedbackPrompts = listOf(
            "Какие давления и приборы изменились первыми?",
            "Отличается ли одна секция, тележка или группа?",
            "Что произошло после снятия нагрузки или команды отпуска?"
        )
    )

    private fun q(
        key: String, text: String, yes: String, no: String, next: String,
        yesNext: String = next, noNext: String = next, unknownNext: String = next
    ) = DiagnosticQuestion(
        key = key,
        text = text,
        yesMeaning = yes,
        noMeaning = no,
        unknownMeaning = "Не удалось подтвердить признак «$text». Одновременно сохраняются обе области поиска: $yes $no Следующий вопрос используется как независимый признак; действия по неподтверждённой ветви не выполнять.",
        yesNextKey = yesNext,
        noNextKey = noNext,
        unknownNextKey = unknownNext
    )

    private fun cab(title: String, action: String, expected: String, abnormal: String) =
        DiagnosticCheck(title, action, expected, abnormal, DiagnosticActionLevel.CAB)

    private fun stop(title: String, action: String, expected: String, abnormal: String) =
        DiagnosticCheck(title, action, expected, abnormal, DiagnosticActionLevel.SAFE_STOP)

    private fun authorized(title: String, action: String, expected: String, abnormal: String) =
        DiagnosticCheck(title, action, expected, abnormal, DiagnosticActionLevel.AUTHORIZED_ONLY)
}
